mapper.insert:
MERGE INTO ST_RVAV_R t USING (
SELECT #{pojo.STCD, jdbcType=VARCHAR} AS STCD, #{pojo.IDTM, jdbcType=VARCHAR} AS IDTM, #{pojo.STTDRCD, jdbcType=VARCHAR} AS STTDRCD, #{pojo.AVZ, jdbcType=DOUBLE} AS AVZ, #{pojo.AVQ, jdbcType=DOUBLE} AS AVQ FROM DUAL
) s ON (t.STCD = s.STCD AND t.IDTM = s.IDTM AND t.STTDRCD = s.STTDRCD) WHEN MATCHED THEN UPDATE SET AVZ = s.AVZ, AVQ = s.AVQ WHEN NOT MATCHED THEN INSERT (STCD, IDTM, STTDRCD, AVZ, AVQ) VALUES (s.STCD, s.IDTM, s.STTDRCD, s.AVZ, s.AVQ)
